| status      = {{ill|Shikinaisha|ja|式内社|1=Shikinaisha|2=ja|3=式内社|qq=draft|1=Shikinaisha|qq=draft|qq=draft|12=simple|13=User:Immanuelle/Shikinaisha|13=User:Immanuelle/Shikinaisha|qq=}} contender, "Fourth Shrine," Sōja contender, former {{ill|Mura-sha|ja|村社|qq=draft|qq=draft|12=simple|13=User:Immanuelle/Mura-sha|qq=}}
| founded     = 
